package fixture

import "testing"

func TestSearch(t *testing.T) {
	nums := []int{1, 3, 5, 7}
	if got := Search(nums, 5); got != 2 {
		t.Fatalf("Search(5) = %d, want 2", got)
	}
	if got := Search(nums, 4); got != -1 {
		t.Fatalf("Search(4) = %d, want -1", got)
	}
}
